  function ppEmbed(doc){ try { if(!doc.__pp){ doc.addFileToVFS("PPr.ttf",PP_R); doc.addFont("PPr.ttf","PP","normal"); doc.addFileToVFS("PPb.ttf",PP_B); doc.addFont("PPb.ttf","PP","bold"); doc.__pp=1; } return "PP"; } catch(e){ return "helvetica"; } }
